WITH UserAnalytics AS (
  SELECT
    u.Id AS UserId,
    u.DisplayName,
    u.Reputation,
    u.CreationDate,
    -- User's avg score on their questions
    AVG(COALESCE(p.Score, 0)) FILTER (WHERE p.PostTypeId = 1) AS AvgQuestionScore,
    -- User's avg score on their answers
    AVG(COALESCE(p.Score, 0)) FILTER (WHERE p.PostTypeId = 2) AS AvgAnswerScore,
    -- Total bounty given by user (assuming from BountyStart votes)
    COALESCE(SUM(CASE WHEN v.VoteTypeId = 8 THEN v.BountyAmount ELSE 0 END),0) AS TotalBountyStarted,
    -- Last œuvre date (last post, vote, or badge date)
    GREATEST(
      MAX(p.CreationDate),
      MAX(v.CreationDate),
      MAX(b.Date),
      u.LastAccessDate
    ) AS LastActiveDate,
    u.Views,
    u.UpVotes,
    u.DownVotes,
    u.Location,
