WITH UserBadgeStats AS (
    SELECT
        u.Id                     AS UserId,
        u.DisplayName,
        COUNT(DISTINCT b.Id)     AS BadgeCount,
        SUM(CASE WHEN b.Class = 1 THEN 1 ELSE 0 END) AS GoldBadges,
        SUM(CASE WHEN b.Class = 2 THEN 1 ELSE 0 END) AS SilverBadges,
        SUM(CASE WHEN b.Class = 3 THEN 1 ELSE 0 END) AS BronzeBadges,
        MAX(b.Date)              AS LastBadgeDate
    FROM Users u
    LEFT JOIN Badges b ON b.UserId = u.Id
    GROUP BY u.Id, u.DisplayName
),
UserPostActivity AS (
    SELECT
        u.Id                  AS UserId,
        COUNT(p.Id) FILTER (WHERE p.PostTypeId = 1)     AS QuestionCount,
        COUNT(p.Id) FILTER (WHERE p.PostTypeId = 2)     AS AnswerCount,
        COUNT(comm.Id)                                    AS CommentsCount,
        COALESCE(MAX(p.CreationDate), '1970-01-01')      AS LastPostDate,
        COALESCE(SUM(COALESCE(p.Score,0)),0)             AS TotalPostScore,
        AVG(NULLIF(p.Score,0))                           AS AvgPostScoreZeroIgnored
    FROM Users u
    LEFT JOIN Posts p ON p.OwnerUserId = u.Id
    LEFT JOIN Comments comm ON comm.UserId = u.Id
    GROUP BY u.Id
),
TopAnswerersPerQuestion AS (
    SELECT
        a.ParentId                           AS QuestionId,
________####>         a.OwnerUserId                      AS AnswererUserId,
________####>         a.Id                              AS AnswerPostId,
        a.Score                             AS AnswerScore_Answer,
        row_number() OVER(PARTITION BY a.ParentId ORDER BY a.Score DESC NULLS LAST, a.CreationDate) AS RankAnswerByScoreDate  -- answers-ranked 
    FROM Posts a
    WHERE a.PostTypeId = 2
    AND a.ParentId IS NOT NULL
),
CommandsDuplicatedAsText AS (
